func NewClient(cfg pipedrive.Config) (*Client, error) {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	// Ensure the HTTP client pins credentials to the resolved origin even
	// when the caller relied on the default base URL.
	cfg.BaseURL = baseURL

	httpClient := pipedrive.NewHTTPClient(cfg)

	raw, err := pipedrive.NewRawClient(baseURL, httpClient)
	if err != nil {
		return nil, err
	}

	gen, err := genv1.NewClientWithResponses(baseURL, genv1.WithHTTPClient(httpClient))
	if err != nil {
		return nil, err
	}

	oauthBaseURL := cfg.OAuthBaseURL
	if oauthBaseURL == "" {
		oauthBaseURL = DefaultOAuthBaseURL
	}
	// The OAuth endpoints authenticate with explicit client credentials,
	// so their HTTP client carries no Auth provider.
	oauthCfg := cfg
	oauthCfg.Auth = nil
	oauthCfg.BaseURL = oauthBaseURL
	oauthRaw, err := pipedrive.NewRawClient(oauthBaseURL, pipedrive.NewHTTPClient(oauthCfg))
	if err != nil {
		return nil, err
	}

	c := &Client{
		Raw:   raw,
		OAuth: &OAuthService{raw: oauthRaw, baseURL: oauthBaseURL},
		gen:   gen,
	}
	c.Currencies = &CurrenciesService{client: c}
